package com.llmcouncil.mobile.data

import com.llmcouncil.mobile.model.ModelSource
import com.llmcouncil.mobile.model.OpenRouterModel
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import okhttp3.MediaType.Companion.toMediaType
import okhttp3.OkHttpClient
import okhttp3.Request
import okhttp3.RequestBody.Companion.toRequestBody
import org.json.JSONArray
import org.json.JSONObject
import java.net.URLEncoder
import java.util.concurrent.TimeUnit

sealed class ApiFailure(message:String):Exception(message){class Authentication(message:String):ApiFailure(message);class Credits(message:String):ApiFailure(message);class RateLimit(message:String):ApiFailure(message);class Unavailable(message:String):ApiFailure(message);class Network(message:String):ApiFailure(message);class Other(message:String):ApiFailure(message)}
class OpenRouterClient(private val settings:SecureSettings){
 private val client=OkHttpClient.Builder().connectTimeout(25,TimeUnit.SECONDS).readTimeout(150,TimeUnit.SECONDS).writeTimeout(30,TimeUnit.SECONDS).build();private val jsonType="application/json; charset=utf-8".toMediaType()
 suspend fun models():List<OpenRouterModel> = withContext(Dispatchers.IO){val all=mutableListOf<OpenRouterModel>();val failures=mutableListOf<String>();fun collect(b:()->List<OpenRouterModel>){try{all+=b()}catch(e:Exception){failures+=(e.message?:e.toString())}};if(settings.getOpenRouterKey().isNotBlank())collect{openRouterModels()};if(settings.getOpenAiKey().isNotBlank())collect{openAiModels()};if(settings.getAnthropicKey().isNotBlank())collect{anthropicModels()};if(settings.getGeminiKey().isNotBlank())collect{geminiModels()};if(all.isEmpty()&&failures.isNotEmpty())throw ApiFailure.Other(failures.joinToString(" · ").take(800));all.distinctBy{it.id}.sortedWith(compareBy<OpenRouterModel>{it.source.ordinal}.thenBy{it.name.lowercase()})}
 private fun openRouterModels():List<OpenRouterModel>{val r=Request.Builder().url("https://openrouter.ai/api/v1/models").header("Authorization","Bearer ${settings.getOpenRouterKey()}").header("Accept","application/json").build();return execute(r){body->val d=JSONObject(body).optJSONArray("data")?:JSONArray();buildList{for(i in 0 until d.length()){val o=d.optJSONObject(i)?:continue;val id=o.optString("id").trim();if(id.isEmpty())continue;val p=o.optJSONObject("pricing");val a=o.optJSONObject("architecture");add(OpenRouterModel(id,o.optString("name",id).ifBlank{id},ModelSource.OPENROUTER,id,o.optInt("context_length",0),p?.optString("prompt")?.takeIf{it.isNotBlank()}?.toDoubleOrNull(),p?.optString("completion")?.takeIf{it.isNotBlank()}?.toDoubleOrNull(),a?.optJSONArray("input_modalities").toStringSet(),a?.optJSONArray("output_modalities").toStringSet(),description=o.optString("description","")))}}}}
 private fun openAiModels():List<OpenRouterModel>{val r=Request.Builder().url("https://api.openai.com/v1/models").header("Authorization","Bearer ${settings.getOpenAiKey()}").build();return execute(r){body->val d=JSONObject(body).optJSONArray("data")?:JSONArray();buildList{for(i in 0 until d.length()){val id=d.optJSONObject(i)?.optString("id")?.trim().orEmpty();if(!looksLikeOpenAiTextModel(id))continue;add(OpenRouterModel(ModelSource.key(ModelSource.OPENAI,id),id,ModelSource.OPENAI,id,inputModalities=setOf("text"),outputModalities=setOf("text"),description="Direct OpenAI API model"))}}}}
 private fun anthropicModels():List<OpenRouterModel>{val r=Request.Builder().url("https://api.anthropic.com/v1/models?limit=100").header("x-api-key",settings.getAnthropicKey()).header("anthropic-version","2023-06-01").build();return execute(r){body->val d=JSONObject(body).optJSONArray("data")?:JSONArray();buildList{for(i in 0 until d.length()){val o=d.optJSONObject(i)?:continue;val id=o.optString("id").trim();if(id.isEmpty())continue;add(OpenRouterModel(ModelSource.key(ModelSource.ANTHROPIC,id),o.optString("display_name",id).ifBlank{id},ModelSource.ANTHROPIC,id,inputModalities=setOf("text"),outputModalities=setOf("text"),description="Direct Anthropic API model"))}}}}
 private fun geminiModels():List<OpenRouterModel>{val r=Request.Builder().url("https://generativelanguage.googleapis.com/v1beta/models").header("x-goog-api-key",settings.getGeminiKey()).build();return execute(r){body->val d=JSONObject(body).optJSONArray("models")?:JSONArray();buildList{for(i in 0 until d.length()){val o=d.optJSONObject(i)?:continue;val methods=o.optJSONArray("supportedGenerationMethods").toStringSet();if(methods.isNotEmpty()&&"generatecontent" !in methods)continue;val id=o.optString("name").removePrefix("models/").trim();if(id.isEmpty()||!id.contains("gemini",true))continue;add(OpenRouterModel(ModelSource.key(ModelSource.GEMINI,id),o.optString("displayName",id).ifBlank{id},ModelSource.GEMINI,id,o.optInt("inputTokenLimit",0),inputModalities=setOf("text"),outputModalities=setOf("text"),description=o.optString("description","Direct Gemini API model")))}}}}
 suspend fun chat(model:String,prompt:String,maxTokens:Int=2048):String=withContext(Dispatchers.IO){val s=ModelSource.fromKey(model);val id=ModelSource.apiIdFromKey(model);when(s){ModelSource.OPENROUTER->openRouterChat(id,prompt,maxTokens);ModelSource.OPENAI->openAiChat(id,prompt,maxTokens);ModelSource.ANTHROPIC->anthropicChat(id,prompt,maxTokens);ModelSource.GEMINI->geminiChat(id,prompt,maxTokens)}}
 private fun openRouterChat(id:String,prompt:String,max:Int):String{if(settings.getOpenRouterKey().isBlank())throw ApiFailure.Authentication("OpenRouter API key is not configured");val p=JSONObject().put("model",id).put("max_tokens",max.coerceIn(8,8192)).put("messages",JSONArray().put(JSONObject().put("role","user").put("content",prompt)));val r=Request.Builder().url("https://openrouter.ai/api/v1/chat/completions").header("Authorization","Bearer ${settings.getOpenRouterKey()}").header("Content-Type","application/json").header("HTTP-Referer","https://github.com/EnigmaThe1/OmniCouncil").header("X-Title","OmniCouncil").post(p.toString().toRequestBody(jsonType)).build();return execute(r){JSONObject(it).getJSONArray("choices").getJSONObject(0).getJSONObject("message").optString("content","")}}
 private fun openAiChat(id:String,prompt:String,max:Int):String{if(settings.getOpenAiKey().isBlank())throw ApiFailure.Authentication("OpenAI API key is not configured");val p=JSONObject().put("model",id).put("input",prompt).put("max_output_tokens",max.coerceIn(16,8192));val r=Request.Builder().url("https://api.openai.com/v1/responses").header("Authorization","Bearer ${settings.getOpenAiKey()}").header("Content-Type","application/json").post(p.toString().toRequestBody(jsonType)).build();return execute(r){body->val a=JSONObject(body).optJSONArray("output")?:JSONArray();buildString{for(i in 0 until a.length()){val c=a.optJSONObject(i)?.optJSONArray("content")?:continue;for(j in 0 until c.length()){val t=c.optJSONObject(j)?.optString("text").orEmpty();if(t.isNotBlank()){if(isNotEmpty())append('\n');append(t)}}}}}}
 private fun anthropicChat(id:String,prompt:String,max:Int):String{if(settings.getAnthropicKey().isBlank())throw ApiFailure.Authentication("Anthropic API key is not configured");val p=JSONObject().put("model",id).put("max_tokens",max.coerceIn(16,8192)).put("messages",JSONArray().put(JSONObject().put("role","user").put("content",prompt)));val r=Request.Builder().url("https://api.anthropic.com/v1/messages").header("x-api-key",settings.getAnthropicKey()).header("anthropic-version","2023-06-01").header("Content-Type","application/json").post(p.toString().toRequestBody(jsonType)).build();return execute(r){body->val a=JSONObject(body).optJSONArray("content")?:JSONArray();buildString{for(i in 0 until a.length()){val t=a.optJSONObject(i)?.takeIf{it.optString("type")=="text"}?.optString("text").orEmpty();if(t.isNotBlank()){if(isNotEmpty())append('\n');append(t)}}}}}
 private fun geminiChat(id:String,prompt:String,max:Int):String{if(settings.getGeminiKey().isBlank())throw ApiFailure.Authentication("Gemini API key is not configured");val e=URLEncoder.encode(id,"UTF-8").replace("%2F","/");val p=JSONObject().put("contents",JSONArray().put(JSONObject().put("role","user").put("parts",JSONArray().put(JSONObject().put("text",prompt))))).put("generationConfig",JSONObject().put("maxOutputTokens",max.coerceIn(16,8192)));val r=Request.Builder().url("https://generativelanguage.googleapis.com/v1beta/models/$e:generateContent").header("x-goog-api-key",settings.getGeminiKey()).header("Content-Type","application/json").post(p.toString().toRequestBody(jsonType)).build();return execute(r){body->val a=JSONObject(body).optJSONArray("candidates")?:JSONArray();val parts=a.optJSONObject(0)?.optJSONObject("content")?.optJSONArray("parts")?:JSONArray();buildString{for(i in 0 until parts.length()){val t=parts.optJSONObject(i)?.optString("text").orEmpty();if(t.isNotBlank()){if(isNotEmpty())append('\n');append(t)}}}}}
 private fun looksLikeOpenAiTextModel(id:String):Boolean{val s=id.lowercase();if(listOf("embedding","whisper","tts","image","dall-e","realtime","audio").any{s.contains(it)})return false;return s.startsWith("gpt-")||s.startsWith("o1")||s.startsWith("o3")||s.startsWith("o4")||s.startsWith("chatgpt-")||s.startsWith("codex-")}
 private fun <T> execute(r:Request,p:(String)->T):T{try{client.newCall(r).execute().use{x->val b=x.body?.string().orEmpty();if(!x.isSuccessful)throw failure(x.code,b);return p(b)}}catch(e:ApiFailure){throw e}catch(e:Exception){throw ApiFailure.Network(e.message?:e.toString())}}
 private fun JSONArray?.toStringSet():Set<String> = if(this==null)emptySet() else buildSet{for(i in 0 until length())optString(i).trim().lowercase().takeIf{it.isNotEmpty()}?.let(::add)}
 private fun failure(code:Int,body:String):ApiFailure{val m=try{val r=JSONObject(body);r.optJSONObject("error")?.optString("message")?.takeIf{it.isNotBlank()}?:r.optString("message").takeIf{it.isNotBlank()}?:body}catch(_:Exception){body};val c=m.ifBlank{"HTTP $code"}.take(700);return when(code){401,403->ApiFailure.Authentication(c);402->ApiFailure.Credits(c);429->ApiFailure.RateLimit(c);404,408,502,503,504->ApiFailure.Unavailable(c);else->ApiFailure.Other("HTTP $code — $c")}}
}
